cation_year": 2026, "type": "conference-paper", "cited_by_count": 1, "open_access": {"is_oa": true, "oa_status": "hybrid", "oa_url": "https://doi.org/10.1145/3793653.3793768", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1145/3793653.3793768", "doi": "https://doi.org/10.1145/3793653.3793768", "is_oa": true, "landing_page_url": "https://doi.org/10.1145/3793653.3793768", "pdf_url": null, "source": {"id": "https://openalex.org/S7407088863", "display_name": "IEEE/ACM International Conference on AI Engineering – Software Engineering for AI (CAIN)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": null, "host_organization_name": null, "host_organization_lineage": [], "host_organization_lineage_names": [], "type": "conference"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Proceedings of the IEEE/ACM 5th International Conference on AI Engineering - Software Engineering for AI", "raw_type": "proceedings-article"}, "abstract": "Cyber-physical systems increasingly rely on foundational models, such as Large Language Models (LLMs) and Vision-Language Models (VLMs) to increase autonomy through enhanced perception, inference, and planning. However, these models also introduce new types of errors, such as hallucinations, over-generalizations, and context misalignments, resulting in incorrect and flawed decisions. To address this, we introduce the concept of Cognition Envelopes, designed to establish reasoning boundaries that constrain AI-generated decisions while complementing the use of meta-cognition and traditional safety envelopes. As with safety envelopes, Cognition Envelopes require practical guidelines and systematic processes for their definition, validation, and assurance. In this paper we describe an LLM/VLM-supported pipeline for dynamic clue analysis within the domain of small autonomous Uncrewed Aerial Systems deployed on Search and Rescue (SAR) missions, and a Cognition Envelope based on probabilistic reasoning and resource analysis. We evaluate the approach through assessing decisions made by our Clue Analysis Pipeline in a series of SAR missions. Finally, we identify key software engineering challenges for systematically designing, implementing, and validating Cognition Envelopes for AI-supported decisions in cyber-physical systems."}]", "excerpt_truncated": true, "source_sha256": "99d1c04bdf90b08b8fda4cb00e74b7ad66b3ec608b9fa014817ff3213dd53623", "verification_required": true, "topic_domain": "unrecognized_reasoning_limits", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11704-024-40231-1", "doi:10.1007/s11704-024-40231-1.pdf", "doi:10.1145/3793653.3793768", "openalex:W4393065402"], "source_candidates": ["https://doi.org/10.1007/s11704-024-40231-1", "https://link.springer.com/content/pdf/10.1007/s11704-024-40231-1.pdf", "https://doi.org/10.1145/3793653.3793768"], "source_candidate_identities": {}}
